$ips = @('192.168.144.1','192.168.144.33','192.168.144.30','192.168.144.254','192.168.144.253')
$ports = @(22,80,443,8728,8729,8291,23,21,161)
foreach ($ip in $ips) {
  $ping = Test-Connection -ComputerName $ip -Count 1 -Quiet -TimeoutSeconds 2
  $open = @()
  foreach ($p in $ports) {
    $t = Test-NetConnection -ComputerName $ip -Port $p -WarningAction SilentlyContinue -InformationLevel Quiet
    if ($t) { $open += $p }
  }
  Write-Output "$ip ping=$ping ports=$($open -join ',')"
}

